## Option A (fastest): single-file tool (no build step)

Create `index.html` and paste this:

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Notes → Summary + Actions</title>
  <style>
    body { font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; max-width: 960px; margin: 32px auto; padding: 0 16px; }
    textarea { width: 100%; min-height: 220px; padding: 12px; font-size: 14px; }
    button { padding: 10px 14px; margin-right: 8px; }
    .row { display: flex; gap: 16px; margin-top: 16px; }
    .col { flex: 1; border: 1px solid #ddd; border-radius: 8px; padding: 12px; }
    h2 { margin: 0 0 8px; font-size: 16px; }
    ul { margin: 8px 0 0 18px; }
    pre { white-space: pre-wrap; margin: 8px 0 0; }
    .muted { color: #666; font-size: 13px; margin-top: 10px; }
  </style>
</head>
<body>
  <h1>Messy notes → summary + 3 actions</h1>

  <textarea id="input" placeholder="Paste notes here..."></textarea>

  <div style="margin-top:12px;">
    <button id="btnSummarize">Summarize</button>
    <button id="btnCopyAll">Copy all</button>
    <span class="muted" id="status"></span>
  </div>

  <div class="row">
    <div class="col">
      <h2>Summary</h2>
      <pre id="summaryOut">—</pre>
    </div>
    <div class="col">
      <h2>Action items (3)</h2>
      <ul id="actionsOut"></ul>
    </div>
  </div>

<script>
/**
 * summarizeNotes(text) -> { summary: string, actions: string[] }
 * Rule-based v0 per your spec. Keep it deterministic and cheap.
 */
function summarizeNotes(text) {
  const normalized = preprocess(text);
  const lines = normalized.split("\n").map(l => l.trim()).filter(Boolean);

  const actions = pickActions(lines);

  const summary = pickSummary(lines);

  return {
    summary: summary || "Notes captured. See actions for next steps.",
    actions: ensureThree(actions, lines)
  };
}

function preprocess(text) {
  if (!text) return "";
  // 1) Normalize line endings, trim, collapse >2 blank lines to 1.
  let t = text.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
  // collapse 2+ blank lines to 1 blank line
  t = t.replace(/\n{3,}/g, "\n\n");
  return t;
}

function pickActions(lines) {
  const verbPrefixes = [
    "call","email","send","book","schedule","draft","write",
    "fix","implement","review","decide","plan"
  ];
  const tagStarts = [
    "todo:","action:","next:","follow up:","follow-up:","owner:"
  ];

  const candidates = [];

  for (const raw of lines) {
    const line = raw.trim();
    const lower = line.toLowerCase();

    const isCheckbox = /^[-*]\s*\[\s*\]\s+/.test(lower);
    const isTaggedStart = tagStarts.some(tag => lower.startsWith(tag));
    const containsTODO = lower.includes("todo");
    const startsWithVerb = verbPrefixes.some(v =>
      lower === v || lower.startsWith(v + " ")
    );

    if (isCheckbox || isTaggedStart || containsTODO || startsWithVerb) {
      candidates.push(cleanAction(line));
    }
  }

  // Dedupe (case-insensitive), drop empties
  const seen = new Set();
  const deduped = [];
  for (const c of candidates) {
    const key = c.toLowerCase();
    if (!c) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(c);
  }

  // If <3, promote question lines: "Resolve: ..."
  if (deduped.length < 3) {
    const questions = lines
      .filter(l => l.trim().endsWith("?"))
      .map(q => ("Resolve: " + truncate(q.trim().replace(/\?+$/, ""), 120)));
    for (const q of questions) {
      const key = q.toLowerCase();
      if (!seen.has(key)) { seen.add(key); deduped.push(q); }
      if (deduped.length >= 3) break;
    }
  }

  // If still <3, fall back to top bullet lines: "Do: ..."
  if (deduped.length < 3) {
    const bullets = lines
      .filter(l => /^[-*•]\s+/.test(l.trim()))
      .map(b => "Do: " + truncate(stripBullet(b.trim()), 120));
    for (const b of bullets) {
      const key = b.toLowerCase();
      if (!seen.has(key)) { seen.add(key); deduped.push(b); }
      if (deduped.length >= 3) break;
    }
  }

  return deduped.slice(0, 3);
}

function cleanAction(line) {
  let t = line.trim();

  // strip checkbox markers: "- [ ]", "* [ ]"
  t = t.replace(/^[-*]\s*\[\s*\]\s+/i, "");

  // strip leading bullets
  t = stripBullet(t);

  // remove leading tags
  t = t.replace(/^(todo:|action:|next:|follow up:|follow-up:|owner:)\s*/i, "");

  // if "owner:" lines are just names, they’re not actions; keep only if there’s more content
  if (/^owner:\s*$/i.test(line.trim())) return "";

  // truncate
  t = truncate(t, 120);

  // ensure it starts like an action (optional mild nudge)
  return t;
}

function stripBullet(s) {
  return s.replace(/^[-*•]\s+/, "").trim();
}

function truncate(s, n) {
  if (s.length <= n) return s;
  return s.slice(0, n - 1).trimEnd() + "…";
}

function pickSummary(lines) {
  if (!lines.length) return "";

  // 1) Prefer explicit headings/decisions
  const priorityStarts = ["decision:", "summary:", "outcome:", "tl;dr", "tldr"];
  for (const l of lines) {
    const lower = l.toLowerCase();
    if (priorityStarts.some(p => lower.startsWith(p))) {
      return l;
    }
  }

  // 2) Otherwise, first paragraph-ish chunk from non-bullet lines up to ~450 chars
  const nonBullet = lines.filter(l => !/^[-*•]\s+/.test(l));
  if (nonBullet.length) {
    let chunk = "";
    for (const l of nonBullet) {
      if ((chunk + " " + l).trim().length > 450) break;
      chunk = (chunk ? chunk + " " : "") + l;
      // stop early if it looks like a paragraph end
      if (chunk.length > 300) break;
    }

    const sentences = sentenceSplit(chunk);
    const picked = sentences.slice(0, 3).filter(Boolean);
    if (picked.length) return picked.join(" ");
  }

  // 3) Mostly bullets: take first 3 bullets
  const bullets = lines.filter(l => /^[-*•]\s+/.test(l));
  if (bullets.length) {
    const b = bullets.slice(0, 3).map(stripBullet).map(s => "• " + s.trim());
    return b.join("\n");
  }

  return "";
}

function sentenceSplit(text) {
  // Cheap sentence split: split on . ! ? followed by space/newline
  return text
    .split(/(?<=[.!?])\s+/)
    .map(s => s.trim())
    .filter(Boolean);
}

function ensureThree(actions, lines) {
  const out = actions.slice(0, 3);
  const fillers = [];

  // Preferably derive a filler from content:
  if (lines.length) fillers.push("Review notes and extract any missing action.");
  fillers.push("Clarify the next step from the notes.");
  fillers.push("Schedule a follow-up / review.");

  while (out.length < 3) out.push(fillers[out.length] || "Clarify next step.");
  return out.slice(0, 3);
}

// --- UI wiring ---
const inputEl = document.getElementById("input");
const summaryEl = document.getElementById("summaryOut");
const actionsEl = document.getElementById("actionsOut");
const statusEl = document.getElementById("status");

document.getElementById("btnSummarize").addEventListener("click", () => {
  const { summary, actions } = summarizeNotes(inputEl.value);

  summaryEl.textContent = summary;

  actionsEl.innerHTML = "";
  actions.forEach(a => {
    const li = document.createElement("li");
    li.textContent = a;
    actionsEl.appendChild(li);
  });

  statusEl.textContent = "Updated.";
  setTimeout(() => statusEl.textContent = "", 1200);
});

document.getElementById("btnCopyAll").addEventListener("click", async () => {
  const { summary, actions } = summarizeNotes(inputEl.value);
  const payload =
`Summary:
${summary}

Actions:
- ${actions.join("\n- ")}
`;
  try {
    await navigator.clipboard.writeText(payload);
    statusEl.textContent = "Copied.";
    setTimeout(() => statusEl.textContent = "", 1200);
  } catch (e) {
    statusEl.textContent = "Copy failed (browser permissions).";
    setTimeout(() => statusEl.textContent = "", 2000);
  }
});
</script>
</body>
</html>
```

